425|				{
426|					tok->err = json_tokener_error_parse_unexpected;
427|					goto out;
428|				}
429|				tok->st_pos++;
430|				(void)ADVANCE_CHAR(str, tok);
431|				if (!PEEK_CHAR(c, tok))
432|				{
433|					/* out of input chars, for now at least */
434|					goto out;
435|				}
436|			}
437|			/* We checked the full length of "Infinity", so create the object.
438|			 * When handling -Infinity, the number parsing code will have dropped
439|			 * the "-" into tok->pb for us, so check it now.
440|			 */
441|			if (printbuf_length(tok->pb) > 0 && *(tok->pb->buf) == '-')
442|			{
443|				is_negative = 1;
444|			}
445|			current = json_object_new_double(is_negative ? -INFINITY : INFINITY);
446|			if (current == NULL)
447|				goto out;
448|			saved_state = json_tokener_state_finish;
449|			state = json_tokener_state_eatws;
450|			goto redo_char;
451|		}
452|		break;
453|		case json_tokener_state_null: /* aka starts with 'n' */
454|		{
455|			int size;
456|			int size_nan;
457|			printbuf_memappend_fast(tok->pb, &c, 1);
458|			size = json_min(tok->st_pos + 1, json_null_str_len);
459|			size_nan = json_min(tok->st_pos + 1, json_nan_str_len);
460|			if ((!(tok->flags & JSON_TOKENER_STRICT) &&
461|			     strncasecmp(json_null_str, tok->pb->buf, size) == 0) ||
462|			    (strncmp(json_null_str, tok->pb->buf, size) == 0))
463|			{
464|				if (tok->st_pos == json_null_str_len)
465|				{
466|					current = NULL;
467|					saved_state = json_tokener_state_finish;
468|					state = json_tokener_state_eatws;
469|					goto redo_char;
470|				}
471|			}
472|			else if ((!(tok->flags & JSON_TOKENER_STRICT) &&
473|			          strncasecmp(json_nan_str, tok->pb->buf, size_nan) == 0) ||
474|			         (strncmp(json_nan_str, tok->pb->buf, size_nan) == 0))
475|			{
476|				if (tok->st_pos == json_nan_str_len)
477|				{
478|					current = json_object_new_double(NAN);
479|					if (current == NULL)
480|						goto out;
481|					saved_state = json_tokener_state_finish;
482|					state = json_tokener_state_eatws;
483|					goto redo_char;
484|				}
485|			}
486|			else
487|			{
488|				tok->err = json_tokener_error_parse_null;
489|				goto out;
490|			}
491|			tok->st_pos++;
492|		}
493|		break;
494|
495|		case json_tokener_state_comment_start:
496|			if (c == '*')
497|			{
498|				state = json_tokener_state_comment;
499|			}
500|			else if (c == '/')
501|			{
502|				state = json_tokener_state_comment_eol;
503|			}
504|			else
505|			{
506|				tok->err = json_tokener_error_parse_comment;
507|				goto out;
508|			}
509|			printbuf_memappend_fast(tok->pb, &c, 1);
510|			break;
511|
512|		case json_tokener_state_comment:
513|		{
514|			/* Advance until we change state */
515|			const char *case_start = str;
516|			while (c != '*')
517|			{
518|				if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
519|				{
520|					printbuf_memappend_fast(tok->pb, case_start,
521|					                        str - case_start);
522|					goto out;
523|				}
524|			}
525|			printbuf_memappend_fast(tok->pb, case_start, 1 + str - case_start);
526|			state = json_tokener_state_comment_end;
527|		}
528|		break;
529|
530|		case json_tokener_state_comment_eol:
531|		{
532|			/* Advance until we change state */
533|			const char *case_start = str;
534|			while (c != '\n')
535|			{
536|				if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
537|				{
538|					printbuf_memappend_fast(tok->pb, case_start,
539|					                        str - case_start);
540|					goto out;
541|				}
542|			}
543|			printbuf_memappend_fast(tok->pb, case_start, str - case_start);
544|			MC_DEBUG("json_tokener_comment: %s\n", tok->pb->buf);
545|			state = json_tokener_state_eatws;
546|		}
547|		break;
548|
549|		case json_tokener_state_comment_end:
550|			printbuf_memappend_fast(tok->pb, &c, 1);
551|			if (c == '/')
552|			{
553|				MC_DEBUG("json_tokener_comment: %s\n", tok->pb->buf);
554|				state = json_tokener_state_eatws;
555|			}
556|			else
557|			{
558|				state = json_tokener_state_comment;
559|			}
560|			break;
561|
562|		case json_tokener_state_string:
563|		{
564|			/* Advance until we change state */
565|			const char *case_start = str;
566|			while (1)
567|			{
568|				if (c == tok->quote_char)
569|				{
570|					printbuf_memappend_fast(tok->pb, case_start,
571|					                        str - case_start);
572|					current =
573|					    json_object_new_string_len(tok->pb->buf, tok->pb->bpos);
574|					if (current == NULL)
575|						goto out;
576|					saved_state = json_tokener_state_finish;
577|					state = json_tokener_state_eatws;
578|					break;
579|				}
580|				else if (c == '\\')
581|				{
582|					printbuf_memappend_fast(tok->pb, case_start,
583|					                        str - case_start);
584|					saved_state = json_tokener_state_string;
585|					state = json_tokener_state_string_escape;
586|					break;
587|				}
588|				if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
589|				{
590|					printbuf_memappend_fast(tok->pb, case_start,
591|					                        str - case_start);
592|					goto out;
593|				}
594|			}
595|		}
596|		break;
597|
598|		case json_tokener_state_string_escape:
599|			switch (c)
600|			{
601|			case '"':
602|			case '\\':
603|			case '/':
604|				printbuf_memappend_fast(tok->pb, &c, 1);
605|				state = saved_state;
606|				break;
607|			case 'b':
608|			case 'n':
609|			case 'r':
610|			case 't':
611|			case 'f':
612|				if (c == 'b')
613|					printbuf_memappend_fast(tok->pb, "\b", 1);
614|				else if (c == 'n')
615|					printbuf_memappend_fast(tok->pb, "\n", 1);
616|				else if (c == 'r')
617|					printbuf_memappend_fast(tok->pb, "\r", 1);
618|				else if (c == 't')
619|					printbuf_memappend_fast(tok->pb, "\t", 1);
620|				else if (c == 'f')
621|					printbuf_memappend_fast(tok->pb, "\f", 1);
622|				state = saved_state;
623|				break;
624|			case 'u':
625|				tok->ucs_char = 0;
626|				tok->st_pos = 0;
627|				state = json_tokener_state_escape_unicode;
628|				break;
629|			default: tok->err = json_tokener_error_parse_string; goto out;
630|			}
631|			break;
632|
633|			// ===================================================
634|
635|		case json_tokener_state_escape_unicode:
636|		{
637|			/* Handle a 4-byte \uNNNN sequence, or two sequences if a surrogate pair */
638|			while (1)
639|			{
640|				if (!c || !strchr(json_hex_chars, c))
641|				{
642|					tok->err = json_tokener_error_parse_string;
643|					goto out;
644|				}
645|				tok->ucs_char |=
646|				    ((unsigned int)jt_hexdigit(c) << ((3 - tok->st_pos) * 4));
647|				tok->st_pos++;
648|				if (tok->st_pos >= 4)
649|					break;
650|
651|				(void)ADVANCE_CHAR(str, tok);
652|				if (!PEEK_CHAR(c, tok))
653|				{
654|					/*
655|					 * We're out of characters in the current call to
656|					 * json_tokener_parse(), but a subsequent call might
657|					 * provide us with more, so leave our current state
658|					 * as-is (including tok->high_surrogate) and return.
659|					 */
660|					goto out;
661|				}
662|			}
663|			tok->st_pos = 0;
