665|			/* Now, we have a full \uNNNN sequence in tok->ucs_char */
666|
667|			/* If the *previous* sequence was a high surrogate ... */
668|			if (tok->high_surrogate)
669|			{
670|				if (IS_LOW_SURROGATE(tok->ucs_char))
671|				{
672|					/* Recalculate the ucs_char, then fall thru to process normally */
673|					tok->ucs_char = DECODE_SURROGATE_PAIR(tok->high_surrogate,
674|					                                      tok->ucs_char);
675|				}
676|				else
677|				{
678|					/* High surrogate was not followed by a low surrogate
679|					 * Replace the high and process the rest normally
680|					 */
681|					printbuf_memappend_fast(tok->pb,
682|					                        (char *)utf8_replacement_char, 3);
683|				}
684|				tok->high_surrogate = 0;
685|			}
686|
687|			if (tok->ucs_char < 0x80)
688|			{
689|				unsigned char unescaped_utf[1];
690|				unescaped_utf[0] = tok->ucs_char;
691|				printbuf_memappend_fast(tok->pb, (char *)unescaped_utf, 1);
692|			}
693|			else if (tok->ucs_char < 0x800)
694|			{
695|				unsigned char unescaped_utf[2];
696|				unescaped_utf[0] = 0xc0 | (tok->ucs_char >> 6);
697|				unescaped_utf[1] = 0x80 | (tok->ucs_char & 0x3f);
698|				printbuf_memappend_fast(tok->pb, (char *)unescaped_utf, 2);
699|			}
700|			else if (IS_HIGH_SURROGATE(tok->ucs_char))
701|			{
702|				/*
703|				 * The next two characters should be \u, HOWEVER,
704|				 * we can't simply peek ahead here, because the
705|				 * characters we need might not be passed to us
706|				 * until a subsequent call to json_tokener_parse.
707|				 * Instead, transition throug a couple of states.
708|				 * (now):
709|				 *   _escape_unicode => _unicode_need_escape
710|				 * (see a '\\' char):
711|				 *   _unicode_need_escape => _unicode_need_u
712|				 * (see a 'u' char):
713|				 *   _unicode_need_u => _escape_unicode
714|				 *      ...and we'll end up back around here.
715|				 */
716|				tok->high_surrogate = tok->ucs_char;
717|				tok->ucs_char = 0;
718|				state = json_tokener_state_escape_unicode_need_escape;
719|				break;
720|			}
721|			else if (IS_LOW_SURROGATE(tok->ucs_char))
722|			{
723|				/* Got a low surrogate not preceded by a high */
724|				printbuf_memappend_fast(tok->pb, (char *)utf8_replacement_char, 3);
725|			}
726|			else if (tok->ucs_char < 0x10000)
727|			{
728|				unsigned char unescaped_utf[3];
729|				unescaped_utf[0] = 0xe0 | (tok->ucs_char >> 12);
730|				unescaped_utf[1] = 0x80 | ((tok->ucs_char >> 6) & 0x3f);
731|				unescaped_utf[2] = 0x80 | (tok->ucs_char & 0x3f);
732|				printbuf_memappend_fast(tok->pb, (char *)unescaped_utf, 3);
733|			}
734|			else if (tok->ucs_char < 0x110000)
735|			{
736|				unsigned char unescaped_utf[4];
737|				unescaped_utf[0] = 0xf0 | ((tok->ucs_char >> 18) & 0x07);
738|				unescaped_utf[1] = 0x80 | ((tok->ucs_char >> 12) & 0x3f);
739|				unescaped_utf[2] = 0x80 | ((tok->ucs_char >> 6) & 0x3f);
740|				unescaped_utf[3] = 0x80 | (tok->ucs_char & 0x3f);
741|				printbuf_memappend_fast(tok->pb, (char *)unescaped_utf, 4);
742|			}
743|			else
744|			{
745|				/* Don't know what we got--insert the replacement char */
746|				printbuf_memappend_fast(tok->pb, (char *)utf8_replacement_char, 3);
747|			}
748|			state = saved_state; // i.e. _state_string or _state_object_field
749|		}
750|		break;
751|
752|		case json_tokener_state_escape_unicode_need_escape:
753|			// We get here after processing a high_surrogate
754|			// require a '\\' char
755|			if (!c || c != '\\')
756|			{
757|				/* Got a high surrogate without another sequence following
758|				 * it.  Put a replacement char in for the high surrogate
759|				 * and pop back up to _state_string or _state_object_field.
760|				 */
761|				printbuf_memappend_fast(tok->pb, (char *)utf8_replacement_char, 3);
762|				tok->high_surrogate = 0;
763|				tok->ucs_char = 0;
764|				tok->st_pos = 0;
765|				state = saved_state;
766|				goto redo_char;
767|			}
768|			state = json_tokener_state_escape_unicode_need_u;
769|			break;
770|
771|		case json_tokener_state_escape_unicode_need_u:
772|			/* We already had a \ char, check that it's \u */
773|			if (!c || c != 'u')
774|			{
775|				/* Got a high surrogate with some non-unicode escape
776|				 * sequence following it.
777|				 * Put a replacement char in for the high surrogate
778|				 * and handle the escape sequence normally.
779|				 */
780|				printbuf_memappend_fast(tok->pb, (char *)utf8_replacement_char, 3);
781|				tok->high_surrogate = 0;
782|				tok->ucs_char = 0;
783|				tok->st_pos = 0;
784|				state = json_tokener_state_string_escape;
785|				goto redo_char;
786|			}
787|			state = json_tokener_state_escape_unicode;
788|			break;
789|
790|			// ===================================================
791|
792|		case json_tokener_state_boolean:
793|		{
794|			int size1, size2;
795|			printbuf_memappend_fast(tok->pb, &c, 1);
796|			size1 = json_min(tok->st_pos + 1, json_true_str_len);
797|			size2 = json_min(tok->st_pos + 1, json_false_str_len);
798|			if ((!(tok->flags & JSON_TOKENER_STRICT) &&
799|			     strncasecmp(json_true_str, tok->pb->buf, size1) == 0) ||
800|			    (strncmp(json_true_str, tok->pb->buf, size1) == 0))
801|			{
802|				if (tok->st_pos == json_true_str_len)
803|				{
804|					current = json_object_new_boolean(1);
805|					if (current == NULL)
806|						goto out;
807|					saved_state = json_tokener_state_finish;
808|					state = json_tokener_state_eatws;
809|					goto redo_char;
810|				}
811|			}
812|			else if ((!(tok->flags & JSON_TOKENER_STRICT) &&
813|			          strncasecmp(json_false_str, tok->pb->buf, size2) == 0) ||
814|			         (strncmp(json_false_str, tok->pb->buf, size2) == 0))
815|			{
816|				if (tok->st_pos == json_false_str_len)
817|				{
818|					current = json_object_new_boolean(0);
819|					if (current == NULL)
820|						goto out;
821|					saved_state = json_tokener_state_finish;
822|					state = json_tokener_state_eatws;
823|					goto redo_char;
824|				}
825|			}
826|			else
827|			{
828|				tok->err = json_tokener_error_parse_boolean;
829|				goto out;
830|			}
831|			tok->st_pos++;
832|		}
833|		break;
834|
835|		case json_tokener_state_number:
836|		{
837|			/* Advance until we change state */
838|			const char *case_start = str;
839|			int case_len = 0;
840|			int is_exponent = 0;
841|			int negativesign_next_possible_location = 1;
842|			if (printbuf_length(tok->pb) > 0)
843|			{
844|				/* We don't save all state from the previous incremental parse
845|				   so we need to re-generate it based on the saved string so far.
846|				 */
847|				char *e_loc = strchr(tok->pb->buf, 'e');
848|				if (!e_loc)
849|					e_loc = strchr(tok->pb->buf, 'E');
850|				if (e_loc)
851|				{
852|					char *last_saved_char =
853|					    &tok->pb->buf[printbuf_length(tok->pb) - 1];
854|					is_exponent = 1;
855|					/* If the "e" isn't at the end, we can't start with a '-' */
856|					if (e_loc != last_saved_char)
857|						negativesign_next_possible_location = -1;
858|					// else leave it set to 1, i.e. start of the new input
859|				}
860|			}
861|			while (c && strchr(json_number_chars, c))
862|			{
863|				++case_len;
864|
865|				/* non-digit characters checks */
866|				/* note: since the main loop condition to get here was
867|				 * an input starting with 0-9 or '-', we are
868|				 * protected from input starting with '.' or
869|				 * e/E.
870|				 */
871|				switch (c)
872|				{
873|				case '.':
874|					if (tok->is_double != 0)
875|					{
876|						/* '.' can only be found once, and out of the exponent part.
877|						 * Thus, if the input is already flagged as double, it
878|						 * is invalid.
879|						 */
880|						tok->err = json_tokener_error_parse_number;
881|						goto out;
882|					}
883|					tok->is_double = 1;
884|					break;
885|				case 'e': /* FALLTHRU */
886|				case 'E':
887|					if (is_exponent != 0)
888|					{
889|						/* only one exponent possible */
890|						tok->err = json_tokener_error_parse_number;
891|						goto out;
892|					}
893|					is_exponent = 1;
894|					tok->is_double = 1;
895|					/* the exponent part can begin with a negative sign */
896|					negativesign_next_possible_location = case_len + 1;
897|					break;
898|				case '-':
899|					if (case_len != negativesign_next_possible_location)
900|					{
901|						/* If the negative sign is not where expected (ie
902|						 * start of input or start of exponent part), the
903|						 * input is invalid.
904|						 */
905|						tok->err = json_tokener_error_parse_number;
906|						goto out;
907|					}
908|					break;
909|				default: break;
910|				}
911|
912|				if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
913|				{
914|					printbuf_memappend_fast(tok->pb, case_start, case_len);
915|					goto out;
916|				}
917|			}
918|			if (case_len > 0)
919|				printbuf_memappend_fast(tok->pb, case_start, case_len);
920|
