922|			if (tok->pb->buf[0] == '-' && case_len <= 1 && (c == 'i' || c == 'I'))
923|			{
924|				state = json_tokener_state_inf;
925|				tok->st_pos = 0;
926|				goto redo_char;
927|			}
928|			if (tok->is_double && !(tok->flags & JSON_TOKENER_STRICT))
929|			{
930|				/* Trim some chars off the end, to allow things
931|				   like "123e+" to parse ok. */
932|				while (printbuf_length(tok->pb) > 1)
933|				{
934|					char last_char = tok->pb->buf[printbuf_length(tok->pb) - 1];
935|					if (last_char != 'e' && last_char != 'E' &&
936|					    last_char != '-' && last_char != '+')
937|					{
938|						break;
939|					}
940|					tok->pb->buf[printbuf_length(tok->pb) - 1] = '\0';
941|					printbuf_length(tok->pb)--;
942|				}
943|			}
944|		}
945|			{
946|				int64_t num64;
947|				uint64_t numuint64;
948|				double numd;
949|				if (!tok->is_double && tok->pb->buf[0] == '-' &&
950|				    json_parse_int64(tok->pb->buf, &num64) == 0)
951|				{
952|					current = json_object_new_int64(num64);
953|					if (current == NULL)
954|						goto out;
955|				}
956|				else if (!tok->is_double && tok->pb->buf[0] != '-' &&
957|				         json_parse_uint64(tok->pb->buf, &numuint64) == 0)
958|				{
959|					if (numuint64 && tok->pb->buf[0] == '0' &&
960|					    (tok->flags & JSON_TOKENER_STRICT))
961|					{
962|						tok->err = json_tokener_error_parse_number;
963|						goto out;
964|					}
965|					if (numuint64 <= INT64_MAX)
966|					{
967|						num64 = (uint64_t)numuint64;
968|						current = json_object_new_int64(num64);
969|						if (current == NULL)
970|							goto out;
971|					}
972|					else
973|					{
974|						current = json_object_new_uint64(numuint64);
975|						if (current == NULL)
976|							goto out;
977|					}
978|				}
979|				else if (tok->is_double &&
980|				         json_tokener_parse_double(
981|				             tok->pb->buf, printbuf_length(tok->pb), &numd) == 0)
982|				{
983|					current = json_object_new_double_s(numd, tok->pb->buf);
984|					if (current == NULL)
