301|int json_object_put(struct json_object *jso)
302|{
303|	if (!jso)
304|		return 0;
305|
306|	/* Avoid invalid free and crash explicitly instead of (silently)
307|	 * segfaulting.
308|	 */
309|	assert(jso->_ref_count > 0);
310|
311|#if defined(HAVE_ATOMIC_BUILTINS) && defined(ENABLE_THREADING)
312|	/* Note: this only allow the refcount to remain correct
313|	 * when multiple threads are adjusting it.  It is still an error
314|	 * for a thread to decrement the refcount if it doesn't "own" it,
315|	 * as that can result in the thread that loses the race to 0
316|	 * operating on an already-freed object.
317|	 */
318|	if (__sync_sub_and_fetch(&jso->_ref_count, 1) > 0)
319|		return 0;
320|#else
321|	if (--jso->_ref_count > 0)
322|		return 0;
323|#endif
324|
325|	if (jso->_user_delete)
326|		jso->_user_delete(jso, jso->_userdata);
327|	switch (jso->o_type)
328|	{
329|	case json_type_object: json_object_object_delete(jso); break;
330|	case json_type_array: json_object_array_delete(jso); break;
331|	case json_type_string: json_object_string_delete(jso); break;
332|	default: json_object_generic_delete(jso); break;
333|	}
334|	return 1;
335|}

