1171|static json_bool json_tokener_validate_utf8(const char c, unsigned int *nBytes)
1172|{
1173|	unsigned char chr = c;
1174|	if (*nBytes == 0)
1175|	{
1176|		if (chr >= 0x80)
1177|		{
1178|			if ((chr & 0xe0) == 0xc0)
1179|				*nBytes = 1;
1180|			else if ((chr & 0xf0) == 0xe0)
1181|				*nBytes = 2;
1182|			else if ((chr & 0xf8) == 0xf0)
1183|				*nBytes = 3;
1184|			else
1185|				return 0;
1186|		}
1187|	}
1188|	else
1189|	{
1190|		if ((chr & 0xC0) != 0x80)
1191|			return 0;
1192|		(*nBytes)--;
1193|	}
1194|	return 1;
1195|}

