186|static int _json_object_to_fd(int fd, struct json_object *obj, int flags, const char *filename)
187|{
188|	int ret;
189|	const char *json_str;
190|	unsigned int wpos, wsize;
191|
192|	filename = filename ? filename : "(fd)";
193|
194|	if (!(json_str = json_object_to_json_string_ext(obj, flags)))
195|	{
196|		return -1;
197|	}
198|
199|	/* CAW: probably unnecessary, but the most 64bit safe */
200|	wsize = (unsigned int)(strlen(json_str) & UINT_MAX);
201|	wpos = 0;
202|	while (wpos < wsize)
203|	{
204|		if ((ret = write(fd, json_str + wpos, wsize - wpos)) < 0)
205|		{
206|			_json_c_set_last_err("json_object_to_file: error writing file %s: %s\n",
207|			                     filename, strerror(errno));
208|			return -1;
209|		}
210|
211|		/* because of the above check for ret < 0, we can safely cast and add */
212|		wpos += (unsigned int)ret;
213|	}
214|
215|	return 0;
216|}

